package net.civeira.phylax.features.oauth.rbac.domain.gateway;

import java.util.Optional;

/**
 * Domain port for verifying relying party identity.
 *
 * Responsibilities: - Resolve a relying party from an API key. - Reject unknown or invalid API
 * keys.
 *
 * Design notes: - Implemented by infrastructure adapters. - Used by RBAC registration endpoints.
 */
public interface PartyVerifierGateway {

  /**
   * Resolves a relying party identifier from an API key.
   *
   * Returns empty when the key is invalid or missing. Used to authorize RBAC registration
   * operations.
   *
   * @param apiKey API key value
   * @return optional relying party identifier
   */
  Optional<String> findOptional(String apiKey);
}
